(()=>{
/* Bài 4 — Vòng lặp for (chuẩn mới 19/10/2026)
   Bối cảnh: quầy trà sữa của lớp tại Lễ hội Mùa Xuân phải làm cùng một việc nhiều lần.
   Tiết 1 = Chặng 1 (for lặp n lần, 3 phần của for, dùng i), tiết 2 = Chặng 2 (biến tổng cộng dồn, n nhập từ cin)
   và Chặng chứng chỉ. Mỗi chặng 6 tab (xem _Nguon_ChuanMoi/VAN_PHONG.md):
   Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
*/
"use strict";

const { cuPhap, scratch } = window.KIT;
const strip = code => window.CPP.stripComments(code);
const khung = than => `#include <iostream>\nusing namespace std;\nint main() {\n${than}\n    return 0;\n}`;

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: dán số thứ tự cho từng ly.
const LY = khung(`    for (int i = 1; i <= 3; i++) {
        cout << "Ly so " << i << endl;
    }
    cout << "Xong!";`);
const LY_LECH = LY.replace("i <= 3", "i < 3");
const MOI = khung(`    for (int i = 0; i < 4; i++) {
        cout << "Tra sua" << endl;
    }
    cout << "Xong!";`);
const MAN_LY = ["Ly so 1\nLy so 2\nLy so 3\nXong!", "Ly so i\nLy so i\nLy so i\nXong!", "Ly so 1\nXong!\nLy so 2\nXong!\nLy so 3\nXong!"];
const MAN_LECH = ["Ly so 1\nLy so 2\nLy so 3\nXong!", "Ly so 1\nLy so 2\nXong!", "Ly so 0\nLy so 1\nLy so 2\nXong!"];
const MAN_MOI = ["Tra sua\nTra sua\nTra sua\nTra sua\nXong!", "Tra sua\nTra sua\nTra sua\nXong!", "Tra sua\nTra sua\nTra sua\nTra sua\nTra sua\nXong!"];
const vongLy = (n, dk, den) => {          // n lần chạy thân; dk: chữ của điều kiện; den: giá trị i ở lần kiểm tra cuối
  const s = [];
  for (let i = 1; i <= n; i++) s.push([4, "", `i=${i} ✓`, "t"], [5, `Ly so ${i}\n`]);
  s.push([4, "", `i=${den} ✗ dừng`, "f"], [7, "Xong!"], [8, "", "kết thúc"]);
  return s;
};
const SO_THU_TU_LOI = khung(`    for (int i = 1; i < 5; i++) {
        cout << "Ly so " << "i" << endl;
    }
    cout << "Xong!";`);

// Chặng 2: cộng dồn doanh thu.
const TONG = khung(`    int tong = 0;
    for (int i = 1; i <= 3; i++) {
        tong = tong + 25000;
    }
    cout << "Doanh thu: " << tong;`);
const TONG_TRONG = khung(`    int tong = 0;
    for (int i = 1; i <= 3; i++) {
        tong = tong + 25000;
        cout << "Doanh thu: " << tong << endl;
    }`);
const NGAY = khung(`    int n;
    cout << "Nhap so ngay: ";
    cin >> n;
    int tong = 0;
    for (int i = 1; i <= n; i++) {
        tong = tong + 30;
    }
    cout << "Tong so ly: " << tong;`);
const vongTong = () => {
  const s = [[4, "", "tong = 0"]];
  for (let i = 1; i <= 3; i++) s.push([5, "", `i=${i} ✓`, "t"], [6, "", `${25000 * i}`]);
  return s.concat([[5, "", "i=4 ✗ dừng", "f"], [8, "Doanh thu: 75000"], [9, "", "kết thúc"]]);
};
const vongTrong = () => {
  const s = [[4, "", "tong = 0"]];
  for (let i = 1; i <= 3; i++) s.push([5, "", `i=${i} ✓`, "t"], [6, "", `${25000 * i}`], [7, `Doanh thu: ${25000 * i}\n`]);
  return s.concat([[5, "", "i=4 ✗ dừng", "f"], [9, "", "kết thúc"]]);
};
const vongNgay = () => {
  const s = [[4, "", "khai báo n"], [5, "Nhap so ngay: "], [6, "4\n", "n = 4"], [7, "", "tong = 0"]];
  for (let i = 1; i <= 4; i++) s.push([8, "", `i=${i} ✓`, "t"], [9, "", `${30 * i}`]);
  return s.concat([[8, "", "i=5 ✗ dừng", "f"], [11, "Tong so ly: 120"], [12, "", "kết thúc"]]);
};
const TONG_NGAY_KHUNG = khung(`    int n;
    cout << "Nhap so ngay: ";
    cin >> n;
    int tong = 0;
    // Viet vong lap for cong don o day: ngay i ban i ly

    cout << "Tong so ly: " << tong;`);
const BANG_GIA_KHUNG = khung(`    int n;
    cout << "Nhap so ly toi da: ";
    cin >> n;
    // In bang gia tu 1 ly den n ly, moi ly 25000
`);
const CHAN_KHUNG = khung(`    int n;
    cout << "Nhap n: ";
    cin >> n;
    // In cac so chan tu 1 den n, moi so mot dong
`);

const boiCanh = (big, text) => `<div class="scene-card"><div class="scene-big">${big}</div><p>${text}</p></div>`;
const sauTab = `<div class="mission-row" style="grid-template-columns:repeat(auto-fit,minmax(96px,1fr))">
  ${["Bối cảnh", "Đoán rồi chạy", "Kiểm chứng", "Ghi nhớ", "Luyện tập", "Phản tư"].map((t, i) => `<div>${i + 1}<small>${t}</small></div>`).join("")}</div>`;
const bonBuoc = `<ol class="think-steps">
  <li><strong>Hiểu đề:</strong> việc gì lặp lại, lặp mấy lần, in gì?</li>
  <li><strong>Chọn biến:</strong> biến đếm <code>i</code>, biến tổng (nếu cần), kiểu <code>int</code>.</li>
  <li><strong>Thiết kế test case trước khi viết:</strong> n nhỏ nhất (0, 1) và một n bình thường.</li>
  <li><strong>Viết → Chạy → So sánh → Sửa</strong> với từng test case.</li></ol>`;
const tuCham = "Chọn mức đúng với mình. Thầy dùng phần này để biết cần giảng thêm chỗ nào.";
const theoDauI = `<table class="test-table"><tr><th>Lượt</th><th>i</th><th><code>i &lt;= 3</code></th><th>Máy làm gì</th></tr>
  <tr><td>1</td><td>1</td><td>đúng</td><td>in <code>Ly so 1</code></td></tr>
  <tr><td>2</td><td>2</td><td>đúng</td><td>in <code>Ly so 2</code></td></tr>
  <tr><td>3</td><td>3</td><td>đúng</td><td>in <code>Ly so 3</code></td></tr>
  <tr><td>4</td><td>4</td><td>sai</td><td>dừng vòng lặp, chạy lệnh sau <code>}</code></td></tr></table>`;
const luuYFor = `<div class="note-card using-note"><strong>⚠️ Ba lỗi hay gặp với vòng lặp</strong>
  <p>1. <strong>Lệch một lần:</strong> <code>i &lt; 3</code> chạy 2 lần (i = 1, 2); <code>i &lt;= 3</code> chạy 3 lần.<br>
  2. <strong>Dấu <code>;</code> ngay sau <code>for (…)</code>:</strong> thân vòng lặp chỉ chạy một lần.<br>
  3. <strong>Khai báo biến tổng bên trong vòng lặp:</strong> tổng bị đặt lại về 0 ở mỗi vòng.</p></div>`;

window.LESSON = {
  id: "bai04",
  number: 4,
  title: "Vòng lặp for",
  story: "Quầy trà sữa làm việc lặp lại",
  badge: { icon: "🔁", name: "Người điều khiển dây chuyền" },
  skills: ["Vòng lặp for", "Ba phần của for", "Biến đếm i", "Đếm ngược, bước nhảy", "Biến tổng cộng dồn", "Kiểm thử n = 0, 1"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Thiếu một dòng (in 1 đến 4 thay vì 5)", "Dùng <code>i &lt; 5</code> thay vì <code>i &lt;= 5</code>", "Lặp n lần từ 1: <code>i &lt;= n</code>; luôn đếm số dòng in ra"],
    ["Thân vòng lặp chỉ chạy một lần", "Có dấu <code>;</code> ngay sau <code>for (…)</code>", "Xoá dấu <code>;</code> đứng sau dấu <code>)</code>"],
    ["In chữ i thay vì số", "Đặt i trong <code>\" \"</code>: <code>cout &lt;&lt; \"i\";</code>", "In giá trị: <code>cout &lt;&lt; i;</code>"],
    ["Tổng chỉ bằng giá trị của vòng cuối", "Khai báo <code>int tong = 0;</code> bên trong vòng lặp", "Khai báo biến tổng ở trước vòng lặp"],
    ["Vòng lặp không dừng", "Bước tăng đi sai hướng (đếm lên mà dùng <code>i--</code>)", "Đếm lên dùng <code>i++</code>, đếm xuống dùng <code>i--</code>"],
    ["Máy không biết tên \"cout\"", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · for ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · VÒNG LẶP for",
      title: "Dán số thứ tự cho từng ly",
      bit: "Chào bạn! Mỗi tab là một phần. Làm xong thì bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Đọc vòng lặp for và đếm đúng số lần lặp", "Gọi tên 3 phần của for: khởi tạo, điều kiện, bước tăng", "Dùng biến i trong thân vòng lặp"],
      flow: [
        { label: "Bối cảnh", title: "Quầy cần dán số cho 100 ly",
          html: boiCanh("Sáng nay quầy pha 100 ly. Mỗi ly cần dán nhãn Ly so 1, Ly so 2, …",
            "Gõ 100 lệnh cout thì quá dài. Việc của bạn: dùng <strong>vòng lặp for</strong> để máy tự lặp lại một lệnh nhiều lần.") + sauTab },
        { label: "Đoán rồi chạy", title: "Đoán trước, rồi chạy để kiểm tra", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: `<p>Ba vòng lặp nhỏ. Mỗi lần: <strong>đọc code</strong> → <strong>chọn</strong> màn hình bạn đoán → bấm <strong>▶ Chạy thử</strong>.</p>
            <p>Khi chạy, nhìn nhãn ở dòng 4: mỗi lượt máy kiểm tra điều kiện một lần (✓ đúng, ✗ sai thì dừng).</p>` },
        { label: "Kiểm chứng", title: "Vòng lặp chạy mấy lần?", tasks: ["c1-solan", "c1-baphan", "c1-dungsai"],
          code: LY, focus: [4],
          html: `<p>Nhìn chương trình bên trái. Trả lời theo số dòng.</p>` },
        { label: "Ghi nhớ", title: "Vòng lặp for",
          html: cuPhap({ ten: "VÒNG LẶP for", mau: ["for (‹khởi tạo›; ‹điều kiện›; ‹bước tăng›) {", "    ‹thân: các lệnh lặp lại›", "}"],
            phan: [["‹khởi tạo›", "<code>int i = 1</code>: chạy <strong>một lần</strong> lúc bắt đầu"], ["‹điều kiện›", "<code>i &lt;= 3</code>: còn đúng thì chạy thân, sai thì dừng"], ["‹bước tăng›", "<code>i++</code>: sau mỗi vòng, i tăng thêm 1"]],
            quyTac: ["Lặp n lần: <code>for (int i = 1; i &lt;= n; i++)</code>.", "Trong thân dùng được <code>i</code>: lượt 1 thì i = 1, lượt 2 thì i = 2…", "Lệnh sau dấu <code>}</code> chạy <strong>một lần</strong>, sau khi vòng lặp xong."],
            viDu: `for (int i = 1; i <= 3; i++) {\n    cout << "Ly so " << i << endl;\n}`, man: "Ly so 1\nLy so 2\nLy so 3" })
            + theoDauI
            + scratch("repeat (3)\nsay [Ly so ...]\nend", "Giống khối <em>lặp lại</em> trong Scratch.") },
        { label: "Luyện tập", title: "Điền, rồi sửa máy dán nhãn", tasks: ["c1-dien", "c1-sua"],
          html: `<p>Làm theo <strong>4 bước của lập trình viên</strong>:</p>${bonBuoc}` },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, showCode: true, icon: "🔮",
          title: "Lần 1 · Dán nhãn 3 ly", prompt: "Đọc vòng lặp. Máy sẽ in gì?",
          code: LY, focus: [4], options: MAN_LY, answer: MAN_LY[0],
          run: { steps: vongLy(3, "i <= 3", 4) },
          whyRight: "Mỗi lượt i tăng 1, nên máy in Ly so 1, 2, 3 rồi mới in Xong!.",
          why: "i ở ngoài \" \" nên máy in giá trị của i: 1, 2, 3. Dòng 7 nằm sau dấu } nên chỉ chạy một lần." },
        { id: "c1-dc2", type: "doanchay", predict: true, showCode: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Đổi <= thành <", prompt: "Dòng 4 dùng <code>i &lt; 3</code>. Máy sẽ in gì?",
          code: LY_LECH, focus: [4], options: MAN_LECH, answer: MAN_LECH[1],
          run: { steps: vongLy(2, "i < 3", 3) },
          whyRight: "Khi i = 3, 3 < 3 là sai, nên máy dừng sau 2 lượt.",
          why: "3 < 3 là sai, nên vòng lặp dừng khi i = 3. Máy chỉ in 2 nhãn. Đây là lỗi lệch một lần." },
        { id: "c1-dc3", type: "doanchay", predict: true, showCode: true, icon: "🔮", after: "c1-dc2",
          title: "Lần 3 · Bắt đầu từ 0", prompt: "Vòng lặp bắt đầu từ <code>i = 0</code> và dùng <code>i &lt; 4</code>. Máy in mấy dòng Tra sua?",
          code: MOI, focus: [4], options: MAN_MOI, answer: MAN_MOI[0],
          run: { steps: [0, 1, 2, 3].flatMap(i => [[4, "", `i=${i} ✓`, "t"], [5, "Tra sua\n"]]).concat([[4, "", "i=4 ✗ dừng", "f"], [7, "Xong!"], [8, "", "kết thúc"]]) },
          whyRight: "i lần lượt là 0, 1, 2, 3: đúng 4 lượt.",
          why: "i lần lượt là 0, 1, 2, 3 (4 lượt). Đến i = 4 thì 4 < 4 sai nên dừng." },
        { id: "c1-solan", type: "choice", icon: "🔍", title: "Thân vòng lặp chạy mấy lần?",
          prompt: "Dòng 5 nằm trong thân vòng lặp. Dòng 5 chạy mấy lần?",
          options: [
            { text: "3 lần" },
            { text: "4 lần", why: "Lượt thứ 4 (i = 4) điều kiện sai nên máy dừng, không chạy dòng 5." },
            { text: "1 lần", why: "Dòng 7 mới chạy một lần. Dòng 5 nằm trong thân vòng lặp." }
          ],
          answer: "3 lần", why: "Đúng. i = 1, 2, 3 thì điều kiện đúng; đến i = 4 thì dừng." },
        { id: "c1-baphan", type: "match", icon: "🔗", title: "Ba phần của for",
          prompt: "Ghép mỗi phần ở dòng 4 với việc nó làm.",
          pairs: [["<code>int i = 1</code>", "Khởi tạo: chạy một lần lúc bắt đầu"], ["<code>i &lt;= 3</code>", "Điều kiện: đúng thì chạy thân, sai thì dừng"], ["<code>i++</code>", "Bước tăng: i tăng thêm 1 sau mỗi vòng"]] },
        { id: "c1-dungsai", type: "truefalse", icon: "✅", title: "Đúng hay sai?",
          prompt: "Chọn Đúng hoặc Sai cho từng câu.",
          items: [
            { text: "Dòng 7 (<code>Xong!</code>) chạy 3 lần.", answer: false, why: "Dòng 7 nằm sau dấu } nên chạy một lần, sau khi vòng lặp xong." },
            { text: "Đổi số 3 ở dòng 4 thành 10 thì máy in Ly so 1 đến Ly so 10.", answer: true },
            { text: "<code>for (int i = 1; i &lt; 3; i++)</code> chạy thân 3 lần.", answer: false, why: "Chỉ i = 1 và i = 2: 2 lần." },
            { text: "<code>i++</code> nghĩa là <code>i = i + 1</code>.", answer: true }
          ] },
        { id: "c1-dien", type: "fill", icon: "✏️", title: "Điền vào chỗ trống",
          prompt: "Điền để máy in các số từ 1 đến 5, mỗi số một dòng.",
          template: `for (int i = 1; i [[0]] 5; i[[1]]) {\n    cout << i << endl;\n}`,
          blanks: [
            { answers: ["<="], options: ["<", "<=", "=="], why: "Muốn có cả số 5 thì dùng <=." },
            { answers: ["++"], options: ["++", "--"], why: "Đếm lên thì i tăng: i++." }
          ],
          screen: "1\n2\n3\n4\n5" },
        { id: "c1-sua", type: "code", icon: "🛠️", title: "Sửa máy dán nhãn",
          prompt: "Máy cần dán nhãn cho 5 ly nhưng đang in sai. Sửa 2 lỗi.",
          card: {
            boiCanh: "Quầy có 5 ly cần dán nhãn Ly so 1 đến Ly so 5. Máy đang thiếu một nhãn và in sai số.",
            bien: [["int i", "int", "biến đếm, là số thứ tự của ly"]],
            nhap: "Không nhập: số ly cố định là 5.",
            xuLy: "Dòng 4: lặp đủ 5 lần (có cả i = 5). Dòng 5: in <strong>giá trị</strong> của i.",
            xuat: "5 dòng <code>Ly so 1</code> … <code>Ly so 5</code>, rồi <code>Xong!</code>.",
            tests: [{ input: "", expected: "Ly so 1\nLy so 2\nLy so 3\nLy so 4\nLy so 5\nXong!", why: "đếm đủ 5 dòng nhãn" }],
            dat: "Giống hệt màn hình mong đợi; giải thích được vì sao i < 5 thiếu một nhãn."
          },
          starter: SO_THU_TU_LOI,
          bugs: [
            { label: "Lệch một lần (i < 5)", fixed: code => /i\s*<=\s*5/.test(strip(code)) },
            { label: "In chữ \"i\" thay vì giá trị", fixed: code => !/"i"/.test(strip(code)) }
          ],
          hints: ["Đếm số dòng nhãn máy in ra: có đủ 5 không? Nhãn có số không?", "Dòng 4 đổi < thành <=. Dòng 5 bỏ dấu \" \" quanh i."] },
        { id: "c1-tucham", type: "self", icon: "🪞", title: "Phản tư Chặng 1",
          prompt: "Mỗi câu chọn một mức.",
          items: ["Mình đếm đúng số lần một vòng for chạy.", "Mình gọi tên được 3 phần của for.", "Mình phân biệt được <code>i &lt; n</code> và <code>i &lt;= n</code>."] }
      ]
    },

    /* ================= CHẶNG 2 · TIẾT 2 · cộng dồn ================= */
    {
      kind: "stage", id: "stage-2", number: 2, nav: "Chặng 2",
      kicker: "CHẶNG 2 · TIẾT 2 · BIẾN TỔNG VÀ CỘNG DỒN",
      title: "Cộng dồn doanh thu",
      bit: "Chặng này máy cộng dồn qua từng vòng. Làm lần lượt từng tab nhé.",
      objectives: ["Khởi tạo biến tổng bằng 0 ở trước vòng lặp", "Cộng dồn trong thân vòng lặp, in tổng sau vòng lặp", "Lặp n lần với n nhập từ bàn phím; thử n = 0 và n = 1"],
      stopText: "Con hướng lên bảng để cả lớp trao đổi. Sau phần làm nhóm, thầy sẽ mở Chặng chứng chỉ.",
      flow: [
